#[cfg(test)]
mod tests {
    use rigorix_engine::effect_commitment::domain::EffectState;

    #[test]
    fn test_effectstate_is_defined() {
        assert_eq!(EffectState::Dispatched.as_str(), "dispatched");
        assert_eq!(EffectState::Committed.as_str(), "committed");
        assert_eq!(EffectState::NotCommitted.as_str(), "not_committed");
        assert_eq!(EffectState::Ambiguous.as_str(), "ambiguous");
        assert_eq!(EffectState::Ambiguous.to_string(), "ambiguous");
    }

    #[test]
    fn test_effectstate_interacts_with_none() {
        // Only observed outcomes are terminal. `Ambiguous` is the state that
        // exists to be left by a resolver, never a tombstone.
        assert!(!EffectState::Dispatched.is_terminal());
        assert!(EffectState::Committed.is_terminal());
        assert!(EffectState::NotCommitted.is_terminal());
        assert!(!EffectState::Ambiguous.is_terminal());
        assert!(EffectState::Ambiguous.is_ambiguous());

        // F1/F2: only an unsettled effect fences the run.
        assert!(!EffectState::Dispatched.blocks_dependents());
        assert!(!EffectState::Committed.blocks_dependents());
        assert!(!EffectState::NotCommitted.blocks_dependents());
        assert!(EffectState::Ambiguous.blocks_dependents());
        assert!(EffectState::Ambiguous.blocks_retry());
        assert!(!EffectState::Committed.blocks_retry());

        // The wire vocabulary is snake_case and round-trips.
        let json = serde_json::to_string(&EffectState::NotCommitted).unwrap();
        assert_eq!(json, "\"not_committed\"");
        let round_trip: EffectState = serde_json::from_str(&json).unwrap();
        assert_eq!(round_trip, EffectState::NotCommitted);
    }
}
